cd /testbed && git apply --recount <<'PATCH'
diff --git a/axum/src/routing/tests/fallback.rs b/axum/src/routing/tests/fallback.rs
--- a/axum/src/routing/tests/fallback.rs
+++ b/axum/src/routing/tests/fallback.rs
@@ -1,7 +1,7 @@
 use tower::ServiceExt;
+use tower_http::services::ServeDir;

 use super::*;
 use crate::middleware::{map_request, map_response};

+#[crate::test]
+async fn fallback_to_nested_static_file_server() {
+    let routes_static = Router::new().nest_service("/", get_service(ServeDir::new(".")));
+    let app = Router::new().fallback_service(routes_static);
+
+    let client = TestClient::new(app);
+
+    let res = client.get("/README.md").send().await;
+    assert_eq!(res.status(), StatusCode::OK);
+    assert_eq!(res.text().await, include_str!("../../../README.md"));
+
+    let res = client.get("/does-not-exist").send().await;
+    assert_eq!(res.status(), StatusCode::NOT_FOUND);
+
+    let res = client.post("/README.md").send().await;
+    assert_eq!(res.status(), StatusCode::METHOD_NOT_ALLOWED);
+}
+
